function validate([edges, maxMoves, n]) {
  if (!Number.isInteger(n) || n < 1 || n > 3000) return 'n is between 1 and 3000.';
  if (!Number.isInteger(maxMoves) || maxMoves < 0 || maxMoves > 1e9) return 'maxMoves is between 0 and 10^9.';
  if (!Array.isArray(edges) || edges.length > Math.min(n * (n - 1) / 2, 10000)) return 'There are too many edges for n nodes.';
  const seen = new Set();
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 3 || !edge.every(Number.isInteger)) return 'Each edge is [u, v, cnt].';
    const [u, v, cnt] = edge;
    if (u < 0 || u >= v || v >= n) return 'Each edge needs 0 <= u < v < n.';
    if (cnt < 0 || cnt > 10000) return 'cnt is between 0 and 10^4.';
    if (seen.has(u * n + v)) return 'Two edges cannot join the same pair of nodes.';
    seen.add(u * n + v);
  }
  return null;
}

