function reachableNodes(edges, maxMoves, n) {
  const graph = Array.from({ length: n }, () => []);
  for (const [u, v, cnt] of edges) {
    graph[u].push([v, cnt + 1]);
    graph[v].push([u, cnt + 1]);
  }
  // Binary min-heap of [distance, node] pairs.
  const heap = [];
  const push = (entry) => {
    heap.push(entry);
    let child = heap.length - 1;
    while (child > 0) {
      const parent = (child - 1) >> 1;
      if (heap[parent][0] <= heap[child][0]) break;
      [heap[parent], heap[child]] = [heap[child], heap[parent]];
      child = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return top;
    heap[0] = last;
    let parent = 0;
    for (;;) {
      const left = 2 * parent + 1;
      const right = left + 1;
      let smallest = parent;
      if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
      if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
      if (smallest === parent) break;
      [heap[parent], heap[smallest]] = [heap[smallest], heap[parent]];
      parent = smallest;
    }
    return top;
  };

  const dist = new Array(n).fill(Infinity);
  dist[0] = 0;
  push([0, 0]);
  while (heap.length > 0) {
    const [d, node] = pop();
    if (d > dist[node]) continue;
    for (const [next, weight] of graph[node]) {
      if (d + weight < dist[next]) {
        dist[next] = d + weight;
        push([dist[next], next]);
      }
    }
  }
  let reachable = 0;
  for (let i = 0; i < n; i++) {
    if (dist[i] <= maxMoves) reachable++;
  }
  for (const [u, v, cnt] of edges) {
    const fromU = Math.max(0, maxMoves - dist[u]);
    const fromV = Math.max(0, maxMoves - dist[v]);
    reachable += Math.min(cnt, fromU + fromV);
  }
  return reachable;
}

