function reachableNodes(edges, maxMoves, n) {
  // Bellman-Ford over the original edges, then check every new node one by one.
  const dist = new Array(n).fill(Infinity);
  dist[0] = 0;
  for (let round = 0; round < n; round++) {
    let changed = false;
    for (const [u, v, cnt] of edges) {
      if (dist[u] + cnt + 1 < dist[v]) { dist[v] = dist[u] + cnt + 1; changed = true; }
      if (dist[v] + cnt + 1 < dist[u]) { dist[u] = dist[v] + cnt + 1; changed = true; }
    }
    if (!changed) break;
  }
  let count = dist.filter(d => d <= maxMoves).length;
  for (const [u, v, cnt] of edges) {
    // The s-th new node from u is s steps from u and cnt + 1 - s steps from v.
    for (let s = 1; s <= cnt; s++) {
      if (Math.min(dist[u] + s, dist[v] + cnt + 1 - s) <= maxMoves) count++;
    }
  }
  return count;
}

