function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 6);
    const edges = [];
    const density = rand();
    for (let u = 0; u < n; u++)
      for (let v = u + 1; v < n; v++)
        if (rand() < density) edges.push([u, v, rand() < 0.2 ? 0 : int(0, 6)]);
    for (let i = edges.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [edges[i], edges[j]] = [edges[j], edges[i]]; }
    return [edges, rand() < 0.1 ? 0 : int(0, 20), n];
  }
  const n = rand() < 0.5 ? 1000 : 2000;
  const m = 2000;
  const used = new Set();
  const edges = [];
  const add = (a, b) => {
    const u = Math.min(a, b), v = Math.max(a, b);
    if (u === v || used.has(u * n + v)) return;
    used.add(u * n + v);
    edges.push([u, v, rand() < 0.1 ? 0 : int(0, 10000)]);
  };
  // A random tree over part of the nodes keeps most of the graph connected to node 0.
  const treeSize = Math.min(n, int(Math.floor(m / 2), m));
  for (let i = 1; i < treeSize; i++) add(i, int(0, i - 1));
  while (edges.length < m) add(int(0, n - 1), int(0, n - 1));
  for (let i = edges.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const roll = rand();
  const maxMoves = roll < 0.25 ? 1000000000 : roll < 0.5 ? int(0, 20000) : int(20000, 200000);
  return [edges, maxMoves, n];
}
